private fun dateText(v:String)=v.replace("T"," ").take(16)
private fun sc(v:String)=when(v.uppercase()){ "PAID","COMPLETED","OK"->OGreen; "PENDING","OPEN","PARTIAL","LOW"->OAmber; "FAILED","EXPIRED","CANCELLED","OVERDUE","VOID"->ORed; else->Color(0xFF64748B) }
