@Composable private fun QrVisual(payload:String){Canvas(Modifier.size(175.dp).padding(8.dp).background(Color.White)){drawQr(payload)}}
private fun DrawScope.drawQr(payload:String){val n=29;val cell=size.minDimension/n;val seed=abs(payload.hashCode());for(y in 0 until n)for(x in 0 until n){var d=((seed+x*31+y*17+x*y*7)and 1)==0;if(x<7&&y<7)d=x==0||y==0||x==6||y==6||(x in 2..4&&y in 2..4);if(x>=n-7&&y<7)d=x==n-1||y==0||x==n-7||y==6||(x in n-5..n-3&&y in 2..4);if(x<7&&y>=n-7)d=x==0||y==n-1||x==6||y==n-7||(x in 2..4&&y in n-5..n-3);if(d)drawRect(Color.Black,androidx.compose.ui.geometry.Offset(x*cell,y*cell),androidx.compose.ui.geometry.Size(cell+.4f,cell+.4f))}}

